#!/usr/bin/env bash
# 045 -- testes da futura V1.0.278 (duas caixas de e-mail das reservas) numa copia do codigo instalado (1.0.277) em /tmp. Nada instalado.
set -u
exec 2>&1
T=$(mktemp -d /tmp/v278.XXXX)
echo "" | base64 -d > $T/p.patch
echo "74321ce491d8bf928a9628062b7b93eecc87e0ade16304f08ab86cbc6f73cb51  $T/p.patch" | sha256sum -c --quiet || { echo "pacote corrompido"; exit 1; }
mkdir -p $T/repo && (cd /opt/PMS-Banana-AI && tar cf - --exclude=.venv --exclude=__pycache__ --exclude='*.pyc' --exclude=node_modules SISTEMA 2>/dev/null) | (cd $T/repo && tar xf - 2>/dev/null)
cd $T/repo && echo "copia: $(grep -oP 'VERSAO = "\K[^"]+' SISTEMA/api/app/versao.py)" && patch -p1 -s --no-backup-if-mismatch < $T/p.patch && echo "pacote 278 aplicado"
cd $T/repo/SISTEMA
P() { env -i PATH=/usr/local/bin:/usr/bin:/bin HOME=$T LANG=C.UTF-8 PYTHONDONTWRITEBYTECODE=1 timeout 600 /opt/PMS-Banana-AI/SISTEMA/.venv/bin/pytest -o addopts="-p no:cacheprovider" "$@" 2>&1; }
echo "== testes novos + 243 + 275"; P -q api/app/entrada/tests/test_v1278_imap_duas_caixas.py api/app/entrada/tests/test_v1243_imap_reservas.py api/app/entrada/tests/test_v1275_airbnb_reservas_pelo_email.py | grep -vE '^\s*$' | tail -50 | cut -c1-240
echo "== suite inteira"; P -q --maxfail=60 api | grep -E '^(FAILED|ERROR)|[0-9]+ (passed|failed|error)' | tail -40 | cut -c1-200
rm -rf $T
